// Sammle alle Eingaben
const items = $input.all();
const firstItem = items[0]?.json || {};

// Original-Daten vom Formular
const originalPrompt = firstItem.originalPrompt || 'Kein Prompt';
const recipientEmail = firstItem.recipientEmail || '';
const markeThema = firstItem.markeThema || 'Allgemein';
const timestamp = firstItem.timestamp || new Date().toLocaleString('de-DE');

// Hilfsfunktion zum Extrahieren der Antwort
function extractResponse(data, platform) {
  try {
    if (!data || data.error) {
      return {
        success: false,
        content: 'API-Fehler: ' + (data?.error?.message || 'Keine Antwort erhalten'),
        sources: []
      };
    }

    let content = '';
    let sources = [];

    switch(platform) {
      case 'ChatGPT':
        content = data.choices?.[0]?.message?.content || 'Keine Antwort';
        break;
      case 'Gemini':
        content = data.candidates?.[0]?.content?.parts?.[0]?.text || 'Keine Antwort';
        break;
      case 'Claude':
        content = data.content?.[0]?.text || 'Keine Antwort';
        break;
      case 'Perplexity':
        content = data.choices?.[0]?.message?.content || 'Keine Antwort';
        // Perplexity liefert echte Citations
        if (data.citations && Array.isArray(data.citations)) {
          sources = data.citations.map((url, idx) => ({
            nummer: idx + 1,
            url: url,
            titel: `Quelle ${idx + 1}`
          }));
        }
        break;
    }

    return {
      success: true,
      content: content,
      sources: sources
    };
  } catch (e) {
    return {
      success: false,
      content: 'Verarbeitungsfehler: ' + e.message,
      sources: []
    };
  }
}

// Verarbeite jede Plattform
const results = {
  originalPrompt,
  recipientEmail,
  markeThema,
  timestamp,
  platforms: {
    chatgpt: extractResponse(items.find(i => i.json?.chatgptResponse)?.json?.chatgptResponse, 'ChatGPT'),
    gemini: extractResponse(items.find(i => i.json?.geminiResponse)?.json?.geminiResponse, 'Gemini'),
    claude: extractResponse(items.find(i => i.json?.claudeResponse)?.json?.claudeResponse, 'Claude'),
    perplexity: extractResponse(items.find(i => i.json?.perplexityResponse)?.json?.perplexityResponse, 'Perplexity')
  }
};

return { json: results };

const data = $input.first().json;

// Hilfsfunktion für Markdown zu HTML (einfach)
function mdToHtml(text) {
  if (!text) return '';
  return text
    .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
    .replace(/\*(.*?)\*/g, '<em>$1</em>')
    .replace(/`(.*?)`/g, '<code>$1</code>')
    .replace(/\n/g, '<br>');
}

// Extrahiere Quellen aus dem Text
function extractSourcesFromText(text) {
  const sources = [];
  // URL Pattern
  const urlPattern = /https?:\/\/[^\s<>"']+/g;
  const urls = text.match(urlPattern) || [];
  urls.forEach((url, idx) => {
    sources.push({
      nummer: idx + 1,
      url: url,
      titel: new URL(url).hostname
    });
  });
  return sources;
}

// Generiere Tabelle für eine Plattform
function generatePlatformSection(name, result, color) {
  const statusIcon = result.success ? '✅' : '❌';
  const sources = result.sources.length > 0 ? result.sources : extractSourcesFromText(result.content);

  let sourcesHtml = '';
  if (sources.length > 0) {
    sourcesHtml = `
      <table style="width: 100%; border-collapse: collapse; margin-top: 10px;">
        <thead>
          <tr style="background-color: #f8f9fa;">
            <th style="padding: 8px; border: 1px solid #dee2e6; text-align: left;">#</th>
            <th style="padding: 8px; border: 1px solid #dee2e6; text-align: left;">Quelle</th>
            <th style="padding: 8px; border: 1px solid #dee2e6; text-align: left;">URL</th>
          </tr>
        </thead>
        <tbody>
          ${sources.map(s => `
            <tr>
              <td style="padding: 8px; border: 1px solid #dee2e6;">${s.nummer}</td>
              <td style="padding: 8px; border: 1px solid #dee2e6;">${s.titel || 'Quelle ' + s.nummer}</td>
              <td style="padding: 8px; border: 1px solid #dee2e6;"><a href="${s.url}" target="_blank">${s.url}</a></td>
            </tr>
          `).join('')}
        </tbody>
      </table>
    `;
  } else {
    sourcesHtml = '<p style="color: #6c757d; font-style: italic;">Keine expliziten Quellen-URLs in der Antwort gefunden.</p>';
  }

  return `
    <div style="margin-bottom: 30px; border: 1px solid #dee2e6; border-radius: 8px; overflow: hidden;">
      <div style="background-color: ${color}; color: white; padding: 15px;">
        <h2 style="margin: 0;">${statusIcon} ${name}</h2>
      </div>
      <div style="padding: 20px;">
        <h3 style="color: #495057;">Antwort:</h3>
        <div style="background-color: #f8f9fa; padding: 15px; border-radius: 4px; max-height: 300px; overflow-y: auto;">
          ${mdToHtml(result.content)}
        </div>
        <h3 style="color: #495057; margin-top: 20px;">Quellenangaben:</h3>
        ${sourcesHtml}
      </div>
    </div>
  `;
}

// HTML Report zusammenbauen
const htmlReport = `
<!DOCTYPE html>
<html lang="de">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>AI Visibility Report</title>
</head>
<body style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; max-width: 900px; margin: 0 auto; padding: 20px; background-color: #ffffff;">

  <div style="text-align: center; margin-bottom: 30px; padding: 30px; background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); border-radius: 12px; color: white;">
    <h1 style="margin: 0 0 10px 0;">🔍 AI Visibility Report</h1>
    <p style="margin: 0; opacity: 0.9;">Multi-Plattform Quellenanalyse</p>
  </div>

  <div style="background-color: #e7f3ff; padding: 20px; border-radius: 8px; margin-bottom: 30px; border-left: 4px solid #0066cc;">
    <h3 style="margin: 0 0 10px 0; color: #0066cc;">📋 Analyse-Details</h3>
    <table style="width: 100%;">
      <tr>
        <td style="padding: 5px 0;"><strong>Zeitpunkt:</strong></td>
        <td>${data.timestamp}</td>
      </tr>
      <tr>
        <td style="padding: 5px 0;"><strong>Thema/Marke:</strong></td>
        <td>${data.markeThema}</td>
      </tr>
      <tr>
        <td style="padding: 5px 0;"><strong>Prompt:</strong></td>
        <td style="font-style: italic;">${data.originalPrompt}</td>
      </tr>
    </table>
  </div>

  <h2 style="color: #333; border-bottom: 2px solid #667eea; padding-bottom: 10px;">Ergebnisse nach Plattform</h2>

  ${generatePlatformSection('ChatGPT 5.2', data.platforms.chatgpt, '#10a37f')}
  ${generatePlatformSection('Google Gemini 3.0', data.platforms.gemini, '#4285f4')}
  ${generatePlatformSection('Claude Sonnet 4.5', data.platforms.claude, '#d97706')}
  ${generatePlatformSection('Perplexity', data.platforms.perplexity, '#20b2aa')}

  <div style="margin-top: 30px; padding: 20px; background-color: #f8f9fa; border-radius: 8px; text-align: center;">
    <h3 style="color: #495057;">📊 Zusammenfassung</h3>
    <p>Dieser Report wurde automatisch generiert, um die Sichtbarkeit und Quellenangaben verschiedener KI-Plattformen zu vergleichen.</p>
    <p style="color: #6c757d; font-size: 12px;">Generiert mit n8n AI Visibility Checker</p>
  </div>

</body>
</html>
`;

return {
  json: {
    htmlReport,
    recipientEmail: data.recipientEmail,
    subject: `AI Visibility Report: ${data.markeThema} - ${data.timestamp}`,
    originalPrompt: data.originalPrompt
  }
};
